-- v1.94-social (D297 follow-up, owner 2026-11-06; CONVENTIONS §10.110.1):
--
-- 1. Weekly task counts (owner): a creator has 6 weekly tasks, a host 4. Two more fixed weekly creator tasks
--    (CREATOR_WEEKLY_LIKES on the audience ladder, CREATOR_WEEKLY_STORIES on the production ladder) and two more fixed
--    weekly host tasks (HOST_WEEKLY_LIVE_DAYS — the new metric HOST_LIVE_DAYS — and HOST_WEEKLY_PK_BATTLES, both on the
--    live-minutes ladder 180 000 … 250 000). They are what a person gets while the generator is off for their audience.
-- 2. The generated catalogue «قم بتوليد 300 ألف مهمة لصانع المحتوى و300 ألف مهمة للمضيف، … حسب المستوى وتدريجياً»: the
--    tasks are generated by code (task-generator.ts), never stored as rows — 315 120 per audience. Each metric and
--    period has ONE template row here (G_CR_<METRIC>_<D|W>, G_HO_<METRIC>_<D|W>; 16 per audience) that holds its switch
--    (enabled) and keys the claims (one per person, template and day or ISO week, as every task). The generated task
--    given to a person is stored in task_assignments.variant (`G.<CR|HO>.<METRIC>.<D|W>.<level>.<step>.<variant>`) with its
--    target, reward and names, fixed for the day or the week. The level is the person's CHARM level (owner: «مستوى
--    الشخص للجاذبية»). Seeded ON for both audiences (task-admin generator off CREATORS|HOSTS switches one off).
--    The template rows' target / reward are the level-0 values (shown in task-admin; the assignment's are used).
--
-- No new table: no GRANT.

-- The new metric.
ALTER TABLE "task_definitions" DROP CONSTRAINT "task_definitions_shape";
ALTER TABLE "task_definitions" ADD CONSTRAINT "task_definitions_shape" CHECK (
    code ~ '^[A-Z][A-Z0-9_]{1,39}$'
    AND metric IN ('WATCH_LIVES', 'FOLLOWS', 'LIVE_CHAT_MESSAGES', 'GIFT_SENDS', 'HOST_LIVE_MINUTES', 'HOST_GIFT_COINS',
                   'WATCH_MINUTES', 'AUDIO_ROOMS', 'LIVE_TAPS', 'NEW_HOST_GIFTS', 'POSTS', 'REELS', 'STORIES',
                   'POST_COMMENTS', 'DM_FRIENDS', 'DM_VOICE_MESSAGES', 'HOST_GIFTS_RECEIVED', 'HOST_GUESTS',
                   'GIFT_COINS_SENT', 'HOST_LUCKY_COINS', 'HOST_GIFT_CHERRIES', 'HOST_LUCKY_CHERRIES',
                   'GIFT_COUNT_SENT', 'CATEGORY_GIFTS_SENT', 'GIFTED_HOSTS', 'FAMILY_JOIN', 'FAMILY_CHAT_MESSAGES',
                   'PK_BATTLES', 'PK_WINS',
                   'REEL_VIEWS_RECEIVED', 'LIKES_RECEIVED', 'COMMENT_REPLIES', 'NEW_FOLLOWERS', 'SHARES_RECEIVED',
                   'HOST_LIVE_DAYS')
    AND target BETWEEN 1 AND 1000000000 AND reward_cherries BETWEEN 1 AND 1000000000
    AND char_length(name_ar) BETWEEN 1 AND 80 AND char_length(name_en) BETWEEN 1 AND 80);

-- A day's or a week's generated task (variant G.…) beside D281's generated pool variants (K.…).
ALTER TABLE "task_assignments" DROP CONSTRAINT "task_assignments_variant_shape";
ALTER TABLE "task_assignments" ADD CONSTRAINT "task_assignments_variant_shape" CHECK (
    ("window_from" IS NULL) = ("window_to" IS NULL)
    AND ("window_from" IS NULL OR ("window_from" >= 0 AND "window_from" < "window_to" AND "window_to" <= 1440))
    AND ("name_ar" IS NULL) = ("name_en" IS NULL)
    AND ("variant" IS NULL OR "variant" LIKE 'K.%' OR "variant" LIKE 'G.%'));

